/// <reference types="vite/client" />
import type { CSSProperties } from 'react'
import sheet from '../assets/character/sprite-sheet.png'
import atlas from '../assets/character/sprite-atlas.json'

// Generated by design/character/build-character.mjs; edit the generator, not the PNG.
export type AgentAnimation = keyof typeof atlas.animations

// One sheet row per animation: CSS steps() walks the row. Reduced motion holds frame 0.
const CSS = `.ra-agent-sprite{display:block;margin:0 0 12px;background-repeat:no-repeat;image-rendering:pixelated;image-rendering:crisp-edges;animation:ra-agent-steps var(--ra-agent-ms) steps(var(--ra-agent-n)) infinite}
@keyframes ra-agent-steps{to{background-position-x:var(--ra-agent-end)}}
@media (prefers-reduced-motion:reduce){.ra-agent-sprite{animation:none}}`

/** Illustration of the agent's current state. Never drives policy or payment. */
export default function AgentSprite({ animation = 'search', scale = 1, label, still = false }: { animation?: AgentAnimation; scale?: number; label?: string; still?: boolean }) {
  const row = atlas.animations[animation], { w, h } = atlas.cell
  const style = {
    animation: still ? 'none' : undefined,
    width: w * scale, height: h * scale,
    backgroundImage: `url(${sheet})`,
    backgroundSize: `${atlas.size.w * scale}px ${atlas.size.h * scale}px`,
    backgroundPosition: `0 ${-row.y * scale}px`,
    '--ra-agent-ms': `${row.frames * row.duration}ms`,
    '--ra-agent-n': row.frames,
    '--ra-agent-end': `${-row.frames * w * scale}px`,
  } as CSSProperties
  return <>
    <style href="ra-agent-sprite" precedence="default">{CSS}</style>
    <span className="ra-agent-sprite" data-animation={animation} style={style} {...label ? { role: 'img', 'aria-label': label } : { 'aria-hidden': true }} />
  </>
}
